-- ============================================================
-- Parts Catalog — Supabase schema
-- Run this once in your Supabase project: SQL Editor → New query → paste → Run
-- ============================================================

-- ---------- Tables ----------

create table if not exists brands (
  id bigint generated always as identity primary key,
  name_en text not null,
  name_ka text not null
);

create table if not exists categories (
  id bigint generated always as identity primary key,
  name_en text not null,
  name_ka text not null
);

create table if not exists parts (
  id bigint generated always as identity primary key,
  code text not null unique,
  title_en text not null,
  title_ka text not null,
  description_en text default '',
  description_ka text default '',
  brand_id bigint references brands(id) on delete set null,
  category_id bigint references categories(id) on delete set null,
  image_path text default '',
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

create index if not exists idx_parts_code on parts(code);
create index if not exists idx_parts_brand on parts(brand_id);
create index if not exists idx_parts_category on parts(category_id);

-- Keep updated_at fresh automatically
create or replace function set_updated_at()
returns trigger as $$
begin
  new.updated_at = now();
  return new;
end;
$$ language plpgsql;

drop trigger if exists parts_updated_at on parts;
create trigger parts_updated_at
  before update on parts
  for each row execute function set_updated_at();

-- ---------- Row Level Security ----------
-- Public (anon key) can READ everything.
-- Only a signed-in user (your one admin account) can WRITE.

alter table brands enable row level security;
alter table categories enable row level security;
alter table parts enable row level security;

drop policy if exists "Public read brands" on brands;
create policy "Public read brands" on brands for select using (true);

drop policy if exists "Authenticated write brands" on brands;
create policy "Authenticated write brands" on brands for all
  using (auth.role() = 'authenticated')
  with check (auth.role() = 'authenticated');

drop policy if exists "Public read categories" on categories;
create policy "Public read categories" on categories for select using (true);

drop policy if exists "Authenticated write categories" on categories;
create policy "Authenticated write categories" on categories for all
  using (auth.role() = 'authenticated')
  with check (auth.role() = 'authenticated');

drop policy if exists "Public read parts" on parts;
create policy "Public read parts" on parts for select using (true);

drop policy if exists "Authenticated write parts" on parts;
create policy "Authenticated write parts" on parts for all
  using (auth.role() = 'authenticated')
  with check (auth.role() = 'authenticated');

-- ---------- Storage bucket for part photos ----------

values ('part-images', 'part-images', true)
on conflict (id) do nothing;

drop policy if exists "Public read part images" on storage.objects;
create policy "Public read part images" on storage.objects
  for select using (bucket_id = 'part-images');

drop policy if exists "Authenticated upload part images" on storage.objects;
create policy "Authenticated upload part images" on storage.objects
  for insert with check (bucket_id = 'part-images' and auth.role() = 'authenticated');

drop policy if exists "Authenticated update part images" on storage.objects;
create policy "Authenticated update part images" on storage.objects
  for update using (bucket_id = 'part-images' and auth.role() = 'authenticated');

drop policy if exists "Authenticated delete part images" on storage.objects;
create policy "Authenticated delete part images" on storage.objects
  for delete using (bucket_id = 'part-images' and auth.role() = 'authenticated');


