insert into parts (code, title_en, title_ka, description_en, description_ka, brand_id, category_id, image_path) values
  ('A0009052504', 'Mercedes W205 / W213 / W222 / X253 Distronic Radar Distance Sensor Module', 'მერსედეს W205 / W213 / W222 / X253 დისტრონიკის მანძილის რადარის სენსორი', 'Original OEM Mercedes-Benz Distronic Radar Distance Sensor Module for W205 / W213 / W222 / X253. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის დისტრონიკის მანძილის რადარის სენსორი (W205 / W213 / W222 / X253). გარანტირებული ხარისხი და თავსებადობა.', 1, 3, '/parts/0009052504.webp'),
  ('A0009052804', 'Mercedes W205 / W213 / W222 / C238 Radar Sensor Distronic Control Unit', 'მერსედეს W205 / W213 / W222 / C238 დისტრონიკის რადარის მართვის ბლოკი', 'Original OEM Mercedes-Benz Radar Sensor Distronic Control Unit for W205 / W213 / W222 / C238. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის დისტრონიკის რადარის მართვის ბლოკი (W205 / W213 / W222 / C238). გარანტირებული ხარისხი და თავსებადობა.', 1, 3, '/parts/0009052804.webp'),
  ('A0009054101', 'Mercedes W177 / W205 / W213 / X253 Blind Spot Radar Sensor Module', 'მერსედეს W177 / W205 / W213 / X253 მკვდარი ზონის (Blind Spot) რადარის სენსორი', 'Original OEM Mercedes-Benz Blind Spot Radar Sensor Module for W177 / W205 / W213 / X253. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის მკვდარი ზონის (Blind Spot) რადარის სენსორი (W177 / W205 / W213 / X253). გარანტირებული ხარისხი და თავსებადობა.', 1, 3, '/parts/000905411.webp'),
  ('A0009054603', 'Mercedes W177 / C118 / W205 / W213 Side Assist Blind Spot Radar Unit', 'მერსედეს W177 / C118 / W205 / W213 გვერდითი მკვდარი ზონის სენსორის მოდული', 'Original OEM Mercedes-Benz Side Assist Blind Spot Radar Unit for W177 / C118 / W205 / W213. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის გვერდითი მკვდარი ზონის სენსორის მოდული (W177 / C118 / W205 / W213). გარანტირებული ხარისხი და თავსებადობა.', 1, 3, '/parts/0009054603.webp'),
  ('A0009054907', 'Mercedes W205 / W213 / W222 / X253 Radar Sensor Control Computer', 'მერსედეს W205 / W213 / W222 / X253 რადარის სენსორების მართვის კომპიუტერი', 'Original OEM Mercedes-Benz Radar Sensor Control Computer for W205 / W213 / W222 / X253. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის რადარის სენსორების მართვის კომპიუტერი (W205 / W213 / W222 / X253). გარანტირებული ხარისხი და თავსებადობა.', 1, 3, '/parts/0009054907.webp'),
  ('A0009055103', 'Mercedes W205 / W213 / X253 / W222 360 Surround View Camera Radar Module', 'მერსედეს W205 / W213 / X253 / W222 360 კამერის და რადარის მართვის მოდული', 'Original OEM Mercedes-Benz 360 Surround View Camera Radar Module for W205 / W213 / X253 / W222. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის 360 კამერის და რადარის მართვის მოდული (W205 / W213 / X253 / W222). გარანტირებული ხარისხი და თავსებადობა.', 1, 3, '/parts/0009055103.webp'),
  ('A0009056911', 'Mercedes W206 / W223 / V167 / X247 Distronic & Surround Camera Control Unit', 'მერსედეს W206 / W223 / V167 / X247 დისტრონიკისა და კამერების მართვის ბლოკი', 'Original OEM Mercedes-Benz Distronic & Surround Camera Control Unit for W206 / W223 / V167 / X247. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის დისტრონიკისა და კამერების მართვის ბლოკი (W206 / W223 / V167 / X247). გარანტირებული ხარისხი და თავსებადობა.', 1, 3, '/parts/0009056911.webp'),
  ('A0009057908', 'Mercedes W205 / W213 / W222 / X253 Collision Avoidance Radar Sensor', 'მერსედეს W205 / W213 / W222 / X253 შეჯახების აცილების რადარის სენსორი', 'Original OEM Mercedes-Benz Collision Avoidance Radar Sensor for W205 / W213 / W222 / X253. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის შეჯახების აცილების რადარის სენსორი (W205 / W213 / W222 / X253). გარანტირებული ხარისხი და თავსებადობა.', 1, 3, '/parts/0009057908.webp'),
  ('A0009058406', 'Mercedes W205 / W213 / X253 / W222 NOX Exhaust Gas Sensor Control Module', 'მერსედეს W205 / W213 / X253 / W222 NOX გამონაბოლქვის სენსორის ბლოკი', 'Original OEM Mercedes-Benz NOX Exhaust Gas Sensor Control Module for W205 / W213 / X253 / W222. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის NOX გამონაბოლქვის სენსორის ბლოკი (W205 / W213 / X253 / W222). გარანტირებული ხარისხი და თავსებადობა.', 1, 3, '/parts/0009058406.webp'),
  ('A0009058802', 'Mercedes W205 / W213 / X253 / W222 Nitrogen Oxide NOX Emissions Sensor', 'მერსედეს W205 / W213 / X253 / W222 აზოტის ჟანგის (NOX) სენსორის მოდული', 'Original OEM Mercedes-Benz Nitrogen Oxide NOX Emissions Sensor for W205 / W213 / X253 / W222. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის აზოტის ჟანგის (NOX) სენსორის მოდული (W205 / W213 / X253 / W222). გარანტირებული ხარისხი და თავსებადობა.', 1, 3, '/parts/0009058802.webp'),
  ('A0009058909', 'Mercedes W205 / W213 / W222 / V167 AdBlue NOX Emission Control Computer', 'მერსედეს W205 / W213 / W222 / V167 AdBlue NOX ემისიების კომპიუტერი', 'Original OEM Mercedes-Benz AdBlue NOX Emission Control Computer for W205 / W213 / W222 / V167. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის AdBlue NOX ემისიების კომპიუტერი (W205 / W213 / W222 / V167). გარანტირებული ხარისხი და თავსებადობა.', 1, 3, '/parts/0009058909.webp'),
  ('A0009059907', 'Mercedes W205 / W213 / X253 / W222 Distronic Plus Front Radar Sensor', 'მერსედეს W205 / W213 / X253 / W222 დისტრონიკ პლუსის წინა რადარი', 'Original OEM Mercedes-Benz Distronic Plus Front Radar Sensor for W205 / W213 / X253 / W222. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის დისტრონიკ პლუსის წინა რადარი (W205 / W213 / X253 / W222). გარანტირებული ხარისხი და თავსებადობა.', 1, 3, '/parts/0009059907.webp'),
  ('A1669003309', 'Mercedes GLE W166 / GLS X166 / GL W166 LED Headlight Control Unit', 'მერსედეს GLE W166 / GLS X166 / GL W166 LED ფარის მართვის მოდული', 'Original OEM Mercedes-Benz LED Headlight Control Unit for GLE W166 / GLS X166 / GL W166. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის LED ფარის მართვის მოდული (GLE W166 / GLS X166 / GL W166). გარანტირებული ხარისხი და თავსებადობა.', 1, 1, '/parts/1669003309.webp'),
  ('A1769001204', 'Mercedes A-Class W176 / CLA C117 / GLA X156 LED Headlamp Controller Unit', 'მერსედეს A-Class W176 / CLA C117 / GLA X156 LED ფარის მართვის ბლოკი', 'Original OEM Mercedes-Benz LED Headlamp Controller Unit for A-Class W176 / CLA C117 / GLA X156. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის LED ფარის მართვის ბლოკი (A-Class W176 / CLA C117 / GLA X156). გარანტირებული ხარისხი და თავსებადობა.', 1, 1, '/parts/1769001204.webp'),
  ('A1779003803', 'Mercedes A-Class W177 / CLA C118 / GLE V167 Multibeam LED Headlight Computer', 'მერსედეს A-Class W177 / CLA C118 / GLE V167 Multibeam LED ფარის კომპიუტერი', 'Original OEM Mercedes-Benz Multibeam LED Headlight Computer for A-Class W177 / CLA C118 / GLE V167. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის Multibeam LED ფარის კომპიუტერი (A-Class W177 / CLA C118 / GLE V167). გარანტირებული ხარისხი და თავსებადობა.', 1, 1, '/parts/1779003803.webp'),
  ('A2048700126', 'Mercedes C-Class W204 / GLK X204 / E-Class W212 Xenon Ballast Control Unit', 'მერსედეს C-Class W204 / GLK X204 / E-Class W212 ქსენონის ბლოკი და მართვის მოდული', 'Original OEM Mercedes-Benz Xenon Ballast Control Unit for C-Class W204 / GLK X204 / E-Class W212. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის ქსენონის ბლოკი და მართვის მოდული (C-Class W204 / GLK X204 / E-Class W212). გარანტირებული ხარისხი და თავსებადობა.', 1, 6, '/parts/2048700126.webp'),
  ('A2048700326', 'Mercedes C-Class W204 / GLK X204 / E-Class W212 HID Xenon Headlight Ballast Module', 'მერსედეს C-Class W204 / GLK X204 / E-Class W212 HID ქსენონის ფარის ბალასტის მოდული', 'Original OEM Mercedes-Benz HID Xenon Headlight Ballast Module for C-Class W204 / GLK X204 / E-Class W212. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის HID ქსენონის ფარის ბალასტის მოდული (C-Class W204 / GLK X204 / E-Class W212). გარანტირებული ხარისხი და თავსებადობა.', 1, 6, '/parts/2048700326.webp'),
  ('A2059006805', 'Mercedes C-Class W205 Facelift / GLC X253 LED Headlight Control Driver Unit', 'მერსედეს C-Class W205 Facelift / GLC X253 LED ფარის მართვის დრაივერის ბლოკი', 'Original OEM Mercedes-Benz LED Headlight Control Driver Unit for C-Class W205 Facelift / GLC X253. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის LED ფარის მართვის დრაივერის ბლოკი (C-Class W205 Facelift / GLC X253). გარანტირებული ხარისხი და თავსებადობა.', 1, 1, '/parts/2059006805.webp'),
  ('A2059009534', 'Mercedes C-Class W205 / GLC X253 LED Main Headlamp Control Module', 'მერსედეს C-Class W205 / GLC X253 LED მთავარი ფარის მართვის მოდული', 'Original OEM Mercedes-Benz LED Main Headlamp Control Module for C-Class W205 / GLC X253. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის LED მთავარი ფარის მართვის მოდული (C-Class W205 / GLC X253). გარანტირებული ხარისხი და თავსებადობა.', 1, 1, '/parts/2059009534.webp'),
  ('A2069007016', 'Mercedes C-Class W206 / S-Class W223 Digital Light Projection Module', 'მერსედეს C-Class W206 / S-Class W223 Digital Light პროექციული ფარის მოდული', 'Original OEM Mercedes-Benz Digital Light Projection Module for C-Class W206 / S-Class W223. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის Digital Light პროექციული ფარის მოდული (C-Class W206 / S-Class W223). გარანტირებული ხარისხი და თავსებადობა.', 1, 2, '/parts/2069007016.webp'),
  ('A2129005324', 'Mercedes E-Class W212 Facelift / CLS W218 LED Voltage Converter Control Module', 'მერსედეს E-Class W212 Facelift / CLS W218 LED ძაბვის გარდამქმნელი მოდული', 'Original OEM Mercedes-Benz LED Voltage Converter Control Module for E-Class W212 Facelift / CLS W218. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის LED ძაბვის გარდამქმნელი მოდული (E-Class W212 Facelift / CLS W218). გარანტირებული ხარისხი და თავსებადობა.', 1, 1, '/parts/2129005324.webp'),
  ('A2129007804', 'Mercedes E-Class W212 Facelift / CLS W218 Full LED Headlight Driver Computer', 'მერსედეს E-Class W212 Facelift / CLS W218 Full LED ფარის დრაივერის კომპიუტერი', 'Original OEM Mercedes-Benz Full LED Headlight Driver Computer for E-Class W212 Facelift / CLS W218. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის Full LED ფარის დრაივერის კომპიუტერი (E-Class W212 Facelift / CLS W218). გარანტირებული ხარისხი და თავსებადობა.', 1, 1, '/parts/2129007804.webp'),
  ('A2129008324', 'Mercedes E-Class W212 / CLS-Class W218 LED Headlamp Power Module', 'მერსედეს E-Class W212 / CLS-Class W218 LED ფარის კვების მოდული', 'Original OEM Mercedes-Benz LED Headlamp Power Module for E-Class W212 / CLS-Class W218. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის LED ფარის კვების მოდული (E-Class W212 / CLS-Class W218). გარანტირებული ხარისხი და თავსებადობა.', 1, 1, '/parts/2129008324.webp'),
  ('A2139000737', 'Mercedes E-Class W213 / C238 / CLS C257 LED Headlight Control Module (Lear PXL3)', 'მერსედეს E-Class W213 / C238 / CLS C257 LED ფარის მოდული (Lear PXL3 star2)', 'Original OEM Mercedes-Benz LED Headlight Control Module (Lear PXL3) for E-Class W213 / C238 / CLS C257. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის LED ფარის მოდული (Lear PXL3 star2) (E-Class W213 / C238 / CLS C257). გარანტირებული ხარისხი და თავსებადობა.', 1, 1, '/parts/2139000737.webp'),
  ('A2139002334 / A2139002434', 'Mercedes E-Class W213 / CLS C257 Dual Multibeam LED Control Unit Pair', 'მერსედეს E-Class W213 / CLS C257 წყვილი Multibeam LED მართვის ბლოკები', 'Original OEM Mercedes-Benz Dual Multibeam LED Control Unit Pair for E-Class W213 / CLS C257. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის წყვილი Multibeam LED მართვის ბლოკები (E-Class W213 / CLS C257). გარანტირებული ხარისხი და თავსებადობა.', 1, 1, '/parts/2139002334%20%20%202139002434.webp'),
  ('A2139002534 / A2139002634', 'Mercedes E-Class W213 / CLS C257 Multibeam LED Headlight Driver Pair', 'მერსედეს E-Class W213 / CLS C257 Multibeam LED ფარის დრაივერების წყვილი', 'Original OEM Mercedes-Benz Multibeam LED Headlight Driver Pair for E-Class W213 / CLS C257. Genuine factory module with guaranteed performance.', 'ორიგინალი OEM მერსედეს-ბენცის Multibeam LED ფარის დრაივერების წყვილი (E-Class W213 / CLS C257). გარანტირებული ხარისხი და თავსებადობა.', 1, 1, '/parts/2139002534%20%202139002634.webp'),
